-- Relacyjnie: albo JEDNA tabela z WIELOMA, CZESTO PUSTYMI kolumnami (autor, gwarancja, rozmiar)
-- albo OSOBNE tabele per kategoria + JOIN - obie opcje SA NIEWYGODNE
CREATE TABLE produkty (
    id INT PRIMARY KEY, nazwa VARCHAR(100), cena DECIMAL(10,2),
    autor VARCHAR(100) NULL,      -- tylko dla ksiazek
    gwarancja_miesiace INT NULL,  -- tylko dla elektroniki
    rozmiar VARCHAR(10) NULL      -- tylko dla ubran
);

// Dokumentowo: KAZDA kategoria MA WYLACZNIE WLASCIWE SOBIE pola, BEZ pustych kolumn
{ "nazwa": "Czysty kod", "cena": 79.90, "autor": "Robert C. Martin" }
{ "nazwa": "Sluchawki", "cena": 299.00, "gwarancjaMiesiace": 24 }

// BLEDNIE: DWA osobne zapisy, BEZ gwarancji, ze OBA sie ZAKONCZA razem
zapiszDokument("zamowienia", noweZamowienie);      // KROK 1: moze sie UDAC
zapiszDokument("platnosci", nowaPlatnosc);          // KROK 2: MOZE zawiesc (blad sieci, awaria)
// JESLI krok 2 zawiedzie PO udanym kroku 1, zamowienie ISTNIEJE
// BEZ odpowiadajacej mu platnosci - NIESPOJNY stan, KTORY trzeba by
// RECZNIE wykrywac i naprawiac W kodzie aplikacji

-- POPRAWNIE: JEDNA transakcja gwarantuje, ze OBA zapisy
-- ZAKONCZA sie RAZEM, ALBO ZOSTANA OBA wycofane
BEGIN TRANSACTION;
INSERT INTO zamowienia (klient_id, kwota) VALUES (42, 149.99);
INSERT INTO platnosci (zamowienie_id, status) VALUES (LAST_INSERT_ID(), 'OPLACONE');
COMMIT;
